package cn.yueji.balance;

import java.time.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class V4710RulesTest {
    LocalDateTime at(String text){return LocalDateTime.parse(text);}
    Ledger.Data data(){Ledger.Data d=new Ledger.Data();Ledger.Account a=new Ledger.Account(1,"银行卡","银行");a.created=at("2026-10-20T10:00");a.opening=100000;d.accounts.add(a);return d;}
    Ledger.Entry income(Ledger.Data d,String time){Ledger.Entry e=new Ledger.Entry(10,true,20000,at(time),"收入","",1);e.category="其他";e.cashLinked=true;d.entries.add(e);return e;}
    @Test public void openingCanPredateAppEntryAndAllowHistoricalInvestment(){Ledger.Data d=data();AccountRecords.setOpening(d,1,at("2026-09-30T12:00"),100000);assertEquals(at("2026-09-30T12:00"),AccountCash.requireAccount(d,1,at("2026-10-01T12:00")).created);LedgerStore.validate(d);assertEquals(1,AccountRecords.rows(d,d.accounts.get(0)).size());}
    @Test public void actualHistoricalFundBuyLinksAfterMovingOpeningEarlier(){Ledger.Data d=data();AccountRecords.setOpening(d,1,at("2026-09-30T12:00"),100000);Ledger.Fund f=FundTransactions.save(d,0,0,"006431",20000,0,at("2026-10-09T10:00"),null,"离线",false,true,1,new TradingCalendar());LedgerStore.validate(d);assertTrue(f.buys.get(0).buyAccountLinked);assertEquals(80000,d.balance(d.accounts.get(0)));assertEquals(0,Ledger.month(d,YearMonth.of(2026,10)).expense);}
    @Test public void initialEditMovesInsteadOfDuplicating(){Ledger.Data d=data();AccountRecords.setOpening(d,1,at("2026-09-30T12:00"),100000);AccountRecords.edit(d,1,at("2026-09-30T12:00"),at("2026-09-29T09:00"),150000);LedgerStore.validate(d);assertEquals(1,d.snapshots.size());assertEquals(150000,d.balance(d.accounts.get(0)));assertEquals(at("2026-09-29T09:00"),d.accounts.get(0).created);}
    @Test public void initialAmountEditRebuildsLinkedCash(){Ledger.Data d=data();AccountRecords.setOpening(d,1,at("2026-10-01T00:00"),100000);income(d,"2026-10-05T12:00");LedgerStore.validate(d);AccountRecords.setOpening(d,1,at("2026-10-01T00:00"),150000);LedgerStore.validate(d);assertEquals(170000,d.balance(d.accounts.get(0)));assertEquals(0,Ledger.month(d,YearMonth.of(2026,10)).expense);}
    @Test public void enablingEarlierDoesNotFillOtherAccounts(){Ledger.Data d=data();Ledger.Snapshot s=new Ledger.Snapshot(5,at("2026-10-05T12:00"),"");Ledger.Account b=new Ledger.Account(2,"现金","现金");b.created=at("2026-09-01T00:00");b.opening=900;d.accounts.add(b);s.balances.put(2L,900L);d.snapshots.add(s);AccountRecords.setOpening(d,1,at("2026-09-30T12:00"),100000);LedgerStore.validate(d);assertTrue(s.partial);assertFalse(s.balances.containsKey(1L));}
    @Test public void deleteOneCellPreservesOtherAccounts(){Ledger.Data d=data();Ledger.Snapshot s=new Ledger.Snapshot(5,at("2026-10-21T12:00"),"");s.balances.put(1L,90000L);s.balances.put(2L,30000L);d.snapshots.add(s);AccountRecords.delete(d,1,s.at);assertEquals(Long.valueOf(30000),d.snapshots.get(0).balances.get(2L));assertTrue(s.partial);}
    @Test public void editSharedSnapshotMovesOnlyOneAccount(){Ledger.Data d=data();Ledger.Snapshot s=new Ledger.Snapshot(5,at("2026-10-21T12:00"),"");s.balances.put(1L,90000L);s.balances.put(2L,30000L);d.snapshots.add(s);AccountRecords.edit(d,1,s.at,at("2026-10-22T12:00"),80000);assertFalse(s.balances.containsKey(1L));assertEquals(Long.valueOf(30000),s.balances.get(2L));assertEquals(80000,d.balance(d.accounts.get(0)));}
    @Test public void deletingOpeningDoesNotBecomeZeroBaseline(){Ledger.Data d=data();AccountRecords.setOpening(d,1,at("2026-10-01T00:00"),100000);MonthLedger.updateAccount(d,1,at("2026-10-10T12:00"),80000);AccountRecords.delete(d,1,at("2026-10-01T00:00"));LedgerStore.validate(d);assertFalse(d.accounts.get(0).openingKnown);assertEquals(0,Ledger.month(d,YearMonth.of(2026,10)).expense);assertNull(AssetHistory.valueAt(d,at("2026-10-05T12:00")));assertEquals(Long.valueOf(80000),AssetHistory.valueAt(d,at("2026-10-10T12:00")));}
    @Test public void deletingOnlyOpeningLeavesPendingAccount(){Ledger.Data d=data();AccountRecords.delete(d,1,d.accounts.get(0).created);LedgerStore.validate(d);assertEquals(1,d.accounts.size());assertFalse(AccountRecords.known(d,d.accounts.get(0)));assertTrue(AccountRecords.rows(d,d.accounts.get(0)).isEmpty());}
    @Test public void generatedBalanceDeletionDoesNotReappearOrDeleteIncome(){Ledger.Data d=data();income(d,"2026-10-21T12:00");LedgerStore.validate(d);AccountRecords.delete(d,1,at("2026-10-21T12:00"));LedgerStore.validate(d);LedgerStore.validate(d);assertTrue(d.snapshots.isEmpty());assertEquals(1,d.entries.size());assertTrue(d.entries.get(0).cashLinked);assertEquals(120000,d.balance(d.accounts.get(0)));assertEquals(Long.valueOf(120000),AssetHistory.valueAt(d,at("2026-10-22T12:00")));}
    @Test public void suppressedFlowStillAffectsLaterGeneratedBalance(){Ledger.Data d=data();income(d,"2026-10-21T12:00");Ledger.Entry second=income(d,"2026-10-22T12:00");second.id=11;LedgerStore.validate(d);AccountRecords.delete(d,1,at("2026-10-21T12:00"));LedgerStore.validate(d);assertEquals(1,d.snapshots.size());assertEquals(140000,d.balance(d.accounts.get(0)));}
    @Test public void generatedBalanceCanBeEditedAndMoved(){Ledger.Data d=data();income(d,"2026-10-21T12:00");LedgerStore.validate(d);AccountRecords.edit(d,1,at("2026-10-21T12:00"),at("2026-10-22T12:00"),115000);LedgerStore.validate(d);assertEquals(1,d.snapshots.size());assertEquals(at("2026-10-22T12:00"),d.latest().at);assertEquals(115000,d.balance(d.accounts.get(0)));}
    @Test public void backupPreservesDeletionAcrossRepeatedRebuilds()throws Exception{Ledger.Data d=data();income(d,"2026-10-21T12:00");LedgerStore.validate(d);AccountRecords.delete(d,1,at("2026-10-21T12:00"));AccountRecords.delete(d,1,d.accounts.get(0).created);LedgerStore.validate(d);String json=LedgerStore.encode(d);assertEquals(16,new JSONObject(json).getInt("version"));Ledger.Data restored=LedgerStore.decode(json);LedgerStore.validate(restored);assertEquals(json,LedgerStore.encode(restored));assertFalse(restored.accounts.get(0).openingKnown);assertTrue(restored.snapshots.isEmpty());}
    @Test public void legacyFixedDaysAreIgnored()throws Exception{JSONObject json=new JSONObject(LedgerStore.encode(data()));json.put("version",14);json.getJSONObject("settings").put("day1",0).put("day2",0).put("checkNotifications",true);Ledger.Data d=LedgerStore.decode(json.toString());LedgerStore.validate(d);assertFalse(new JSONObject(LedgerStore.encode(d)).getJSONObject("settings").has("day1"));}
    @Test public void legacyVersionsDefaultToKnownOpening()throws Exception{for(int version=1;version<=14;version++){JSONObject json=new JSONObject(LedgerStore.encode(data()));json.put("version",version);json.getJSONArray("accounts").getJSONObject(0).remove("openingKnown");json.getJSONArray("accounts").getJSONObject(0).remove("skippedCashObservations");Ledger.Data restored=LedgerStore.decode(json.toString());LedgerStore.validate(restored);assertTrue(restored.accounts.get(0).openingKnown);assertEquals(100000,restored.accounts.get(0).opening);}}
    @Test public void realZeroOpeningIsNotMissing(){Ledger.Data d=data();AccountRecords.setOpening(d,1,d.accounts.get(0).created,0);LedgerStore.validate(d);assertTrue(AccountRecords.known(d,d.accounts.get(0)));assertEquals(Long.valueOf(0),AssetHistory.valueAt(d,d.accounts.get(0).created));}
    @Test(expected=IllegalArgumentException.class) public void cannotMoveOpeningPastLinkedTransaction(){Ledger.Data d=data();income(d,"2026-10-21T12:00");AccountRecords.setOpening(d,1,at("2026-10-22T12:00"),100000);}
    @Test(expected=IllegalArgumentException.class) public void cannotMoveOpeningPastExistingObservation(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-21T12:00"),90000);AccountRecords.setOpening(d,1,at("2026-10-22T12:00"),100000);}
    @Test(expected=IllegalArgumentException.class) public void duplicateDestinationIsRejected(){Ledger.Data d=data();MonthLedger.updateAccount(d,1,at("2026-10-21T12:00"),90000);MonthLedger.updateAccount(d,1,at("2026-10-22T12:00"),80000);AccountRecords.edit(d,1,at("2026-10-21T12:00"),at("2026-10-22T12:00"),70000);}
    @Test(expected=IllegalArgumentException.class) public void futureOpeningRejected(){Ledger.Data d=data();AccountRecords.setOpening(d,1,LocalDateTime.now().plusDays(1),100000);}
    @Test(expected=IllegalArgumentException.class) public void malformedOpeningFlagRejected()throws Exception{JSONObject json=new JSONObject(LedgerStore.encode(data()));json.getJSONArray("accounts").getJSONObject(0).put("openingKnown","false");LedgerStore.decode(json.toString());}
}
